// Recordatorios exclusivamente para WhatsApp API (Meta/Chatwoot).
// Configura CHATWOOT_URL, CHATWOOT_API_TOKEN, SUPABASE_URL y
// SUPABASE_SERVICE_ROLE_KEY como variables de entorno del workflow.
const env = (typeof $env !== 'undefined' ? $env : process.env);
const CHATWOOT_URL = String(env.CHATWOOT_URL || 'https://crmesteban.duckdns.org').replace(/\/$/, '');
const TOKEN = String(env.CHATWOOT_API_TOKEN || '');
const SUPABASE_URL = String(env.SUPABASE_URL || 'https://qrrkokfmbdtodrqbfehs.supabase.co').replace(/\/$/, '');
const SUPABASE_KEY = String(env.SUPABASE_SERVICE_ROLE_KEY || '');
const ACCOUNT_ID = String(env.CHATWOOT_ACCOUNT_ID || '1');
if (!TOKEN || !SUPABASE_KEY) throw new Error('Faltan CHATWOOT_API_TOKEN o SUPABASE_SERVICE_ROLE_KEY');
const chatHeaders = { 'api_access_token': TOKEN, 'Content-Type': 'application/json' };
const sbHeaders = { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}`, 'Content-Type': 'application/json', 'Prefer': 'return=representation' };
const getJson = (url, headers) => this.helpers.httpRequest({ method: 'GET', url, headers, json: true });

const normalizar = (v) => String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/[ -]+/g, '_');
// Lead nuevo queda deliberadamente fuera. Solo se aceptan Datos y Sin respuesta.
const ETAPAS = {
  datos: new Set(['datos', 'datos_templo', 'solicitar_datos', 'solicitud_datos', 'en_datos']),
  sinRespuesta: new Set(['sin_respuesta', 'sin_respuesta_templo', 'no_contesta', 'no_contesta_templo', 'sinrespuesta', 'nocontesta'])
};
const etapaDe = (v) => { const k = normalizar(v); for (const [nombre, claves] of Object.entries(ETAPAS)) if (claves.has(k)) return nombre; return null; };
const plantillas = {
  datos: [
    'Hola {{nombre}}. Para avanzar con tu consulta gratuita estamos esperando los datos solicitados. Cuando puedas, envíanos los nombres y las fotos que te pedimos.',
    'Hola {{nombre}}, recuerda que la consulta es gratuita. Nos faltan los datos, nombres o fotos solicitados para poder continuar. ¿Puedes enviarlos por aquí?',
    'Hola {{nombre}}. Seguimos atentos a los datos de tu consulta. Envíanos las fotos y los nombres solicitados cuando te quede cómodo; la consulta continúa siendo gratuita y sin compromiso.',
    'Hola {{nombre}}. Este es nuestro último recordatorio sobre los datos pendientes. Cuando nos envíes los nombres o fotos podremos continuar con tu consulta gratuita.'
  ],
  sinRespuesta: [
    'Hola {{nombre}}. Queríamos saber en cuánto tiempo puedes atender la llamada. ¿Qué hora te queda mejor?',
    'Hola {{nombre}}, seguimos pendientes de poder hablar contigo. ¿Puedes indicarnos a qué hora te queda mejor atender la llamada?',
    'Hola {{nombre}}. Cuando tengas disponibilidad, dinos qué día y a qué hora podemos llamarte. Así coordinamos la atención contigo.',
    'Hola {{nombre}}. Aprovechamos que todavía estamos dentro del horario de atención para coordinar tu llamada. ¿A qué hora te queda mejor que te atendamos?'
  ]
};
const ahora = Math.floor(Date.now() / 1000);
const conversaciones = [];
for (let pagina = 1; pagina <= 5; pagina++) {
  const respuesta = await getJson(`${CHATWOOT_URL}/api/v1/accounts/${ACCOUNT_ID}/conversations?status=open&per_page=100&page=${pagina}`, chatHeaders);
  const lote = respuesta?.data?.payload || [];
  conversaciones.push(...lote);
  if (lote.length < 100) break;
}
const salidas = [];
for (const conv of conversaciones) {
  const labels = Array.isArray(conv.labels) ? conv.labels.map(normalizar) : [];
  if (labels.includes('bot_pausado') || labels.includes('recordatorios_pausados') || labels.includes('lead_perdido')) continue;
  const cwId = conv.id;
  const query = `${SUPABASE_URL}/rest/v1/conversaciones?chatwoot_conversation_id=eq.${encodeURIComponent(cwId)}&fuente=eq.meta_business&select=id,cliente_id,numero_whatsapp,fuente,clientes!inner(id,estado,grupo,es_spam)`;
  const vinculadas = await getJson(query, sbHeaders);
  const dbConv = Array.isArray(vinculadas) ? vinculadas[0] : null;
  const cliente = dbConv?.clientes;
  if (!dbConv || !cliente || cliente.es_spam === true || cliente.grupo !== 'templo') continue;
  const etapa = etapaDe(cliente.estado);
  if (!etapa) continue;

  // Se busca la última respuesta REAL del cliente, aunque después haya respondido
  // el agente. Por eso no se usa last_activity_at ni se filtra por último mensaje.
  const mensajesData = await getJson(`${CHATWOOT_URL}/api/v1/accounts/${ACCOUNT_ID}/conversations/${cwId}/messages?per_page=100`, chatHeaders);
  const mensajes = mensajesData?.payload || mensajesData?.data?.payload || [];
  const entrantes = mensajes.filter(m => m.message_type === 0 || m.message_type === 'incoming');
  if (!entrantes.length) continue;
  const ultimaRespuesta = Math.max(...entrantes.map(m => Number(m.created_at || 0)).filter(Boolean));
  if (!ultimaRespuesta) continue;
  const horasDesdeRespuesta = (ahora - ultimaRespuesta) / 3600;

  // Cuatro envíos, contados por cliente y etapa: 30 min, 3 h, 12 h y 23:30 h.
  const logUrl = `${SUPABASE_URL}/rest/v1/recordatorios_whatsapp?cliente_id=eq.${cliente.id}&etapa=eq.${encodeURIComponent(cliente.estado)}&tipo=eq.${encodeURIComponent(etapa)}&select=plantilla,enviado_en&order=enviado_en.desc&limit=10`;
  const logs = await getJson(logUrl, sbHeaders);
  const intentos = Array.isArray(logs) ? logs.length : 0;
  if (intentos >= 4) continue;
  const umbrales = [0.5, 3, 12, 23.5];
  if (horasDesdeRespuesta < umbrales[intentos]) continue;

  const nombre = String(conv.meta?.sender?.name || '').trim();
  const primerNombre = nombre && normalizar(nombre) !== 'cliente' ? nombre.split(' ')[0] : '';
  const base = plantillas[etapa][intentos].replace('{{nombre}}', primerNombre).replace('Hola .', 'Hola');
  const telefono = String(dbConv.numero_whatsapp || conv.meta?.sender?.phone_number || conv.meta?.sender?.identifier || '').replace(/[^0-9]/g, '');
  if (!telefono || !base) continue;
  salidas.push({ json: { conversationId: cwId, conversacionId: dbConv.id, clienteId: cliente.id, etapa, estado: cliente.estado, telefono, mensaje: base, intento: intentos + 1, nombre: primerNombre, ultimaRespuestaCliente: ultimaRespuesta, horasDesdeRespuesta: Math.floor(horasDesdeRespuesta) } });
}
return salidas;

const env = (typeof $env !== 'undefined' ? $env : process.env);
const url = String(env.CHATWOOT_URL || 'https://crmesteban.duckdns.org').replace(/\/$/, '');
const token = String(env.CHATWOOT_API_TOKEN || '');
const account = String(env.CHATWOOT_ACCOUNT_ID || '1');
const d = $input.item.json;
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${url}/api/v1/accounts/${account}/conversations/${d.conversationId}/messages`,
    headers: { 'api_access_token': token, 'Content-Type': 'application/json' },
    body: { content: d.mensaje, message_type: 'outgoing', private: false },
    json: true
  });
  return [{ json: { ...d, enviado: true, error: null } }];
} catch (e) {
  return [{ json: { ...d, enviado: false, error: e.message } }];
}

const env = (typeof $env !== 'undefined' ? $env : process.env);
const sb = String(env.SUPABASE_URL || 'https://qrrkokfmbdtodrqbfehs.supabase.co').replace(/\/$/, '');
const key = String(env.SUPABASE_SERVICE_ROLE_KEY || '');
const d = $input.item.json;
if (d.enviado !== true) return [{ json: d }];
const fecha = new Date().toISOString().slice(0, 10);
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${sb}/rest/v1/recordatorios_whatsapp`,
    headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json', 'Prefer': 'resolution=ignore-duplicates,return=minimal' },
    body: { cliente_id: d.clienteId, conversacion_id: d.conversacionId, etapa: d.estado, tipo: d.etapa, plantilla: d.intento, fecha, mensaje: d.mensaje, proveedor: 'chatwoot' },
    json: true
  });
  return [{ json: { ...d, registrado: true } }];
} catch (e) {
  return [{ json: { ...d, registrado: false, errorRegistro: e.message } }];
}
